Record Producto
  Define nombre As String;
  Define precio As Integer;
EndRecord

Algorithm Kiosco
  Define jugo As Producto <- Producto("Jugo", 3);
  Write jugo.nombre, " ", jugo.precio;
EndAlgorithm

Record Contacto
  Define nombre, telefono As String;
  Define mes As Integer;
EndRecord

Algorithm Agenda
  Define agenda As Vector<Contacto> <- vector();
  Define porMes As Dictionary<Integer, Integer> <- dictionary();
  Define nombre, telefono As String;
  Define mes As Integer;
  For i <- 1 To 4 Do
    Read nombre;
    Read telefono;
    Read mes;
    agenda.append(Contacto(nombre, telefono, mes));
    Switch porMes.find(mes) Do
      Some(cantidad): porMes[mes] <- cantidad + 1;
      None: porMes[mes] <- 1;
    EndSwitch
  EndFor
  Read nombre;
  Define encontrado As String <- "No está";
  For Each contacto In agenda Do
    If contacto.nombre = nombre And encontrado = "No está" Then
      encontrado <- contacto.telefono;
    EndIf
  EndFor
  Write nombre, ": ", encontrado;
  For Each clave In porMes.keys() Do
    Write "Mes ", clave, ": ", porMes[clave];
  EndFor
EndAlgorithm
